from collections import defaultdict

class Solution:
    def largestWordCount(self, messages: list[str], senders: list[str]) -> str:
        total_words = defaultdict(int)
        for msg, sender in zip(messages, senders):
            words = msg.count(" ") + 1
            total_words[sender] += words
        return max(total_words.keys(), key=lambda s: (total_words[s], s))

class Solution {
public:
    std::string largestWordCount(std::vector<std::string>& messages, std::vector<std::string>& senders) {
        std::unordered_map<std::string, int> total_words;
        for (int i = 0; i < (int)messages.size(); ++i) {
            int words = 1;
            for (char c : messages[i]) if (c == ' ') ++words;
            total_words[senders[i]] += words;
        }
        std::string best = "";
        int max_cnt = -1;
        for (const auto& [sender, cnt] : total_words) {
            if (cnt > max_cnt || (cnt == max_cnt && sender > best)) {
                max_cnt = cnt;
                best = sender;
            }
        }
        return best;
    }
};

class Solution {
    public String largestWordCount(String[] messages, String[] senders) {
        java.util.Map<String, Integer> totalWords = new java.util.HashMap<>();
        for (int i = 0; i < messages.length; i++) {
            int words = 1;
            for (int k = 0; k < messages[i].length(); k++) {
                if (messages[i].charAt(k) == ' ') words++;
            }
            totalWords.put(senders[i], totalWords.getOrDefault(senders[i], 0) + words);
        }
        String best = "";
        int maxCnt = -1;
        for (java.util.Map.Entry<String, Integer> entry : totalWords.entrySet()) {
            String sender = entry.getKey();
            int cnt = entry.getValue();
            if (cnt > maxCnt || (cnt == maxCnt && sender.compareTo(best) > 0)) {
                maxCnt = cnt;
                best = sender;
            }
        }
        return best;
    }
}

var largestWordCount = function(messages, senders) {
    const totalWords = new Map();
    for (let i = 0; i < messages.length; i++) {
        let words = 1;
        const msg = messages[i];
        for (let j = 0; j < msg.length; j++) {
            if (msg.charCodeAt(j) === 32) words++;
        }
        totalWords.set(senders[i], (totalWords.get(senders[i]) || 0) + words);
    }
    let best = "";
    let maxCnt = -1;
    for (const [sender, cnt] of totalWords.entries()) {
        if (cnt > maxCnt || (cnt === maxCnt && sender > best)) {
            maxCnt = cnt;
            best = sender;
        }
    }
    return best;
};
